package com.mdiaz.trxlauncher;
import android.content.*;import android.graphics.Color;import android.provider.Settings;import android.widget.*;
final class SettingsScreen extends ScrollView{
 SettingsScreen(MainActivity a){super(a);setFillViewport(true);LinearLayout root=Ui.col(a);root.setPadding(24,18,24,24);addView(root);root.addView(Ui.text(a,"TRX LAUNCHER SETTINGS",30,Color.WHITE,true));String[] names={"Appearance","Navigation","Media Access","OBD-II / OBDLink MX+","Home & Work","Quick Launch","Audio","Permissions","Backup & Reset","About"};for(String n:names){Button b=Ui.button(a,n,false);root.addView(b,new LinearLayout.LayoutParams(-1,70));Ui.margins(b,0,6,0,6);if(n.startsWith("Media"))b.setOnClickListener(v->a.requestMediaAccess());if(n.startsWith("OBD"))b.setOnClickListener(v->{try{a.startActivity(new Intent(Settings.ACTION_BLUETOOTH_SETTINGS));}catch(Throwable ignored){}});if(n.startsWith("Permissions"))b.setOnClickListener(v->a.startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+a.getPackageName()))));if(n.startsWith("Backup"))b.setOnClickListener(v->new android.app.AlertDialog.Builder(a).setTitle("Reset TRX Launcher?").setMessage("This clears launcher preferences, favorites and paired in-app choices. Android Bluetooth pairings are not removed.").setNegativeButton("Cancel",null).setPositiveButton("Reset",(d,w)->{a.getSharedPreferences("trx",0).edit().clear().apply();a.recreate();}).show());}}
}
